45	 * 当前需包含原有的91092/91093的通信域、原有的91095的通信域void
46	 * *指针、及新独立算子架构的通信域（支持91092/91093/91095...）。
47	 */
48	enum class CollCommInitMode {
49	    fullMode, // 全功能模式：给A5及后续新架构使用，完整的CollComm初始化和资源管理
50	    simpleMode // 简化模式：给A2/A3老芯片使用，由于架构限制，仅将RankGraph、MyRank等放入CollComm管理
51	};
52	
53	class CollComm {
54	public:
55	    CollComm(
56	        void* comm, uint32_t rankId, const std::string& commName, const ManagerCallbacks& callbacks,
57	        CollCommInitMode initMode = CollCommInitMode::fullMode);
58	    ~CollComm();
59	
60	    // 初始化通信域
61	    HcclResult Init(void* rankGraph, aclrtBinHandle binHandle, HcclMem cclBuffer, uint32_t opExpansionMode = 0);
62	
63	    inline CommConfig& GetCommConfig() { return config_; }
64	    inline RankGraph* GetRankGraph() { return rankgraph_; }
65	    inline CommEngineResMgr* GetCommEngineResMgr() { return commEngineResMgr_.get(); }
66	    inline ContextManager* GetContextManager() { return contextMgr_.get(); }
67	    inline CommMemMgr* GetCommMemMgr() { return commMemMgr_.get(); }
68	    inline ChannelManager* GetChannelManager() { return channelMgr_.get(); }
69	    void* GetCommunicatorV2() { return comm_; }
70	
71	    // 获取MyRank
72	    MyRank* GetMyRank() const { return myRank_.get(); }
73	
74	    // 获取Rank ID
75	    uint32_t GetMyRankId() const;
76	
77	    // 获取devicelogicId
78	    s32 GetDeviceLogicId() const { return deviceLogicId_; }
79	
80	    // 是否为全功能模式（fullMode），供外部 owner 在注册/注销前判断是否需要管理
81	    bool IsFullMode() const { return initMode_ == CollCommInitMode::fullMode; }
82	
83	    // 获取Rank数量
84	    uint32_t GetRankSize() const
85	    {
86	        if (rankgraph_ == nullptr) {
87	            HCCL_ERROR("[CollComm]get ranksize failed");
88	            return 0;
89	        }
90	        uint32_t rankSize{0};
91	        HcclResult ret = rankgraph_->GetRankSize(&rankSize);
92	        if (ret != 0) {
93	            HCCL_ERROR("[CollComm]get ranksize failed");
94	            return 0;
95	        }
96	        return rankSize;
97	    }
98	
99	    // 获取HcclCommDfx
100	    HcclCommDfx* GetHcclCommDfx() { return hcclCommDfx_.get(); }
101	    std::function<HcclResult(u32, u32, const Hccl::TaskParam&, u64)> GetDfxCallback()
102	    {
103	        if (hcclCommDfx_ == nullptr) {
104	            HCCL_ERROR("[CollComm]CollComm DfxCallBack failed. hcclCommDfx is nullptr");
105	            return nullptr;
106	        }
107	        return hcclCommDfx_->GetCallback();
108	    }
109	    const std::string& GetCommId() const { return commId_; }
110	    HcclResult
111	    GetHDCommunicate(HDCommunicateParams& kfcControlTransferH2DParams, HDCommunicateParams& kfcStatusTransferD2HParams);
112	    Hccl::ErrorMessageReport GetAicpuTaskException();
113	    HcclResult GetParentRankId(u32& parentRankId) const;
114	    uint32_t UpdateIndex();
