131	    HcclResult DestroyAicpuComm();
132	    HcclResult InitHDCommunicate();
133	    HcclResult InitTaskExceptionHandler();
134	    HcclResult InitKfcAndRegisterCollComm();
135	    HcclResult GetRankIpPortMap();
