44	    HcclOpInfoCtx& LegacyGetOpHcomInfo(uint32_t devId);
45	    HcclOpInfoCtx& LegacyGetHcclExistDeviceOpInfoCtx(s32& devId);
46	    HcclOpInfoCtx& LegacyGetHcclOpInfoCtx(s32& devId);
47	
48	private:
49	    std::unordered_map<std::string, CollComm*> allCollComms_;
