55	    std::array<HcclOpInfoCtx, MAX_MODULE_DEVICE_NUM + 1> opHcomInfos_;
56	    std::array<bool, MAX_MODULE_DEVICE_NUM + 1> baseCommInited_{};
57	    std::mutex opHcomInfosMutex_;
