40	CollComm::~CollComm()
41	{
42	    if (!IsFullMode()) { // SimpleMode是简化版collComm，只初始化了myrank、rankgraph未初始化以下资源，不需要析构处理
43	        return;
44	    }
45	
46	    // 先注销TaskException，再销毁通信域资源，防止通信域资源销毁后rts回调TaskException
47	    hcomm::TaskExceptionHost* handler = hcomm::TaskExceptionHost::GetInstance(deviceLogicId_);
48	    if (handler != nullptr) {
49	        (void)handler->UnRegister(reinterpret_cast<u64>(this));
50	    }
51	
52	    CHK_PRT(HcclBinaryUnLoad());
53	
54	    // 兜底释放所有team的syncMem本地内存
55	    HcclTeamMgr::GetInstance().ClearByCollComm(this);
56	    HCCL_INFO("[CollComm][~CollComm] collComm deinit");
57	    // dpu的兜底上报 - 异常退出时捕获异常避免二次崩溃
58	    if (hcclCommDfx_ != nullptr) {
59	        // 析构属于最终阶段，不再存储数据，直接上报
60	        DECTOR_TRY_CATCH("CollComm", hcclCommDfx_->ReportAllTasks(false));
61	    }
62	    (void)DestroyAicpuComm();
63	    HCCL_RUN_INFO("[CollComm][~CollComm] cclBuffer free, commId[%s].", commId_.c_str());
64	}
