76	CollComm::InitSimpleMode(void* rankGraph, aclrtBinHandle binHandle, HcclMem cclBuffer, uint32_t opExpansionMode)
77	{
78	    CHK_PTR_NULL(rankGraph);
79	
80	    EXCEPTION_HANDLE_BEGIN
81	
82	    CHK_RET(DlHalFunction::GetInstance().DlHalFunctionInit());
83	
84	    // SimpleMode: A2/A3的RankGraph是保存在hccl::Communicator中的静态对象裸指针，CollComm不负责释放
85	    rankgraph_ = static_cast<RankGraph*>(rankGraph);
