167	HcclResult CollComm::RegisterSymmetricMemoryResource(void* ptr, size_t size, SymmetricMemoryResource& resource)
168	{
169	    CHK_PTR_NULL(ptr);
170	    CHK_PRT_RET(
171	        size == 0, HCCL_ERROR("[CollComm][RegisterSymmetricMemoryResource] invalid symmetric memory size 0."),
172	        HCCL_E_PARA);
173	    CHK_SMART_PTR_NULL(myRank_);
174	
175	    CommMems* commMems = myRank_->GetCommMems();
176	    CHK_PTR_NULL(commMems);
177	
178	    CommMem commMem{};
179	    commMem.type = COMM_MEM_TYPE_DEVICE;
180	    commMem.addr = ptr;
181	    commMem.size = static_cast<uint64_t>(size);
182	    resource.memTag = std::string(HCCL_SYMMETRIC_MEMORY_TAG_PREFIX) + commId_ + "_addr_"
183	                      + std::to_string(reinterpret_cast<uintptr_t>(ptr)) + "_size_" + std::to_string(size);
184	    HcclResult ret = commMems->CommRegMem(resource.memTag, commMem, &resource.memHandle);
185	    CHK_PRT_RET(
186	        ret != HCCL_SUCCESS,
187	        HCCL_ERROR(
188	            "[CollComm][RegisterSymmetricMemoryResource] CommRegMem failed, tag[%s], ptr[%p], "
189	            "size[%zu], ret[%d].",
190	            resource.memTag.c_str(), ptr, size, ret),
191	        ret);
192	
193	    HCCL_RUN_INFO(
194	        "[CollComm][RegisterSymmetricMemoryResource] register symmetric memory success, group[%s], "
195	        "tag[%s], ptr[%p], size[%zu], memHandle[%p].",
196	        commId_.c_str(), resource.memTag.c_str(), ptr, size, resource.memHandle);
197	    return HCCL_SUCCESS;
198	}
