275	HcclResult CollComm::RegisterPendingSymmetricMemHandles(std::vector<HcclMemHandle>& memHandles)
276	{
277	    memHandles.clear();
278	    if (symmetricMemory_ == nullptr) {
279	        return HCCL_SUCCESS;
280	    }
281	
282	    std::vector<SymmetricMemoryRegisterInfo> registerInfos;
283	    // HcclCommSymWinRegister只记录窗口，真正CommRegMem延迟到ChannelAcquire阶段执行。
284	    CHK_RET(symmetricMemory_->GetPendingRegisterInfos(registerInfos));
285	    if (registerInfos.empty()) {
286	        return HCCL_SUCCESS;
287	    }
288	
289	    std::vector<std::pair<void*, SymmetricMemoryResource>> registeredResources;
290	    for (const SymmetricMemoryRegisterInfo& registerInfo : registerInfos) {
291	        SymmetricMemoryResource resource;
292	        HcclResult ret = RegisterSymmetricMemoryResource(registerInfo.userVa, registerInfo.userSize, resource);
293	        if (ret != HCCL_SUCCESS) {
294	            HCCL_ERROR(
295	                "[CollComm][RegisterPendingSymmetricMemHandles] register symmetric memory failed, "
296	                "win[%p], userVa[%p], size[%zu], ret[%d].",
297	                registerInfo.devWin, registerInfo.userVa, registerInfo.userSize, ret);
298	            for (const auto& registeredResource : registeredResources) {
299	                symmetricMemory_->RemoveRegisteredMemoryResource(registeredResource.first);
300	                UnregisterSymmetricMemoryResource(registeredResource.second);
301	            }
302	            return ret;
303	        }
304	
305	        ret = symmetricMemory_->SetRegisteredMemoryResource(registerInfo.devWin, resource);
306	        if (ret != HCCL_SUCCESS) {
307	            HCCL_ERROR(
308	                "[CollComm][RegisterPendingSymmetricMemHandles] save symmetric memory resource failed, "
309	                "win[%p], userVa[%p], size[%zu], ret[%d].",
310	                registerInfo.devWin, registerInfo.userVa, registerInfo.userSize, ret);
311	            UnregisterSymmetricMemoryResource(resource);
312	            for (const auto& registeredResource : registeredResources) {
313	                symmetricMemory_->RemoveRegisteredMemoryResource(registeredResource.first);
314	                UnregisterSymmetricMemoryResource(registeredResource.second);
315	            }
316	            return ret;
317	        }
318	        registeredResources.emplace_back(registerInfo.devWin, resource);
319	        // 仅返回本次新注册的memHandle，避免普通URMA重复携带历史对称内存句柄。
320	        memHandles.emplace_back(static_cast<HcclMemHandle>(resource.memHandle));
321	    }
322	
323	    return HCCL_SUCCESS;
324	}
