342	HcclResult CollComm::DestroyAicpuComm()
343	{
344	    CHK_PTR_NULL(callbacks_.getAicpuCommState);
345	    if (callbacks_.getAicpuCommState()) {
346	        CHK_SMART_PTR_NULL(kfcControlTransferH2D_);
347	        CHK_SMART_PTR_NULL(kfcStatusTransferD2H_);
348	
349	        Hccl::KfcCommand opCmd = Hccl::KfcCommand::DESTROY_AICPU_COMM;
350	        CHK_RET(kfcControlTransferH2D_->Put(0, sizeof(Hccl::KfcCommand), reinterpret_cast<uint8_t*>(&opCmd)));
351	        HCCL_RUN_INFO(
352	            "[%s]group[%s] send Hccl::KfcCommand[%d] success", __func__, commId_.c_str(), static_cast<int>(opCmd));
353	
354	        Hccl::KfcExecStatus opInfo;
355	        constexpr u32 WAIT_CMD_TIMEOUT = 10 * 1000; // 最大等待10秒
356	        auto timeout = std::chrono::milliseconds(WAIT_CMD_TIMEOUT);
357	        auto startTime = std::chrono::steady_clock::now();
358	
359	        while (true) {
360	            CHK_RET(kfcStatusTransferD2H_->Get(0, sizeof(Hccl::KfcExecStatus), reinterpret_cast<uint8_t*>(&opInfo)));
361	            if (opInfo.kfcStatus == Hccl::KfcStatus::DESTROY_AICPU_COMM_DONE) {
362	                HCCL_RUN_INFO("[%s]get Hccl::KfcStatus[%d] success", __func__, static_cast<int>(opInfo.kfcStatus));
363	                return HCCL_SUCCESS;
364	            } else if ((std::chrono::steady_clock::now() - startTime) >= timeout) {
365	                HCCL_ERROR(
366	                    "[%s]timeout, maxTime[%u ms] and get the opExecStatus is [%s].", __func__, WAIT_CMD_TIMEOUT,
367	                    opInfo.kfcStatus.Describe().c_str());
368	                return HCCL_E_TIMEOUT;
369	            }
370	            usleep(TEN_MILLISECOND_OF_USLEEP);
371	        }
372	    }
373	    return HCCL_SUCCESS;
374	}
