507	HcclResult CollComm::GetRankIpPortMap()
508	{
509	    Hccl::HcclCommunicator* commV2 = static_cast<Hccl::HcclCommunicator*>(comm_);
510	    CHK_PTR_NULL(commV2);
511	    CHK_RET(commV2->GetRankIpPortMap(rankIpPortMap_));
512	    CHK_PTR_NULL(rankIpPortMap_);
513	    // rankIpPortMap_ 在单卡多进程场景下，用于保证端口不冲突
514	    // 该映射表记录了：Rank ID -> (IP地址 -> 已占用的端口号)
515	    return HCCL_SUCCESS;
516	}
517	
518	HcclResult CollComm::GetHcclBinHandle(aclrtBinHandle& binHcclHandle)
519	{
520	    std::lock_guard<std::mutex> lock(binHcclmutex_);
521	    HCCL_DEBUG("[%s] GetHcclBinHandle", __func__);
522	    if (binHcclHandle_ == nullptr) {
523	        std::string hcclJsonPath;
524	        CHK_RET(GetKernelFilePath(hcclJsonPath));
525	        hcclJsonPath += "libscatter_aicpu_kernel.json";
526	        HcclResult ret
527	            = LoadBinaryFromFile(hcclJsonPath.c_str(), ACL_RT_BINARY_LOAD_OPT_CPU_KERNEL_MODE, 0, binHcclHandle_);
528	        CHK_PRT_RET(
529	            ret != HCCL_SUCCESS,
530	            HCCL_ERROR(
531	                "[%s]errNo[0x%016llx]load aicpu file fail, path[%s] optionType[%u] cpuKernelMode[%u].", __func__,
532	                HCCL_ERROR_CODE(ret), hcclJsonPath.c_str(), ACL_RT_BINARY_LOAD_OPT_CPU_KERNEL_MODE, 0),
533	            ret);
534	
535	        HCCL_INFO(
536	            "[%s]load aicpu file success, path[%s] optionType[%u] cpuKernelMode[%u].", __func__, hcclJsonPath.c_str(),
537	            ACL_RT_BINARY_LOAD_OPT_CPU_KERNEL_MODE, 0);
538	    }
539	    binHcclHandle = binHcclHandle_;
540	    return HCCL_SUCCESS;
541	}
542	
543	HcclResult CollComm::HcclBinaryUnLoad()
544	{
545	    std::lock_guard<std::mutex> lock(binHcclmutex_);
546	    if (binHcclHandle_ == nullptr) {
547	        HCCL_RUN_WARNING("[%s] binHcclHandle is nullptr", __func__);
548	        return HCCL_SUCCESS;
549	    }
550	
551	    HCCL_DEBUG("[%s]aclrtBinaryUnLoad binHcclHandle", __func__);
552	    aclError ret = aclrtBinaryUnLoad(binHcclHandle_);
553	    binHcclHandle_ = nullptr;
554	    if (ret != 0) {
555	        HCCL_RUN_WARNING("[%s]aclrtBinaryUnLoad failed, aclRet[%d]", __func__, ret);
556	        return HCCL_E_INTERNAL;
557	    }
558	    return HCCL_SUCCESS;
559	}
